def md_to_html(text):
    """Convert markdown to HTML with proper formatting."""
    lines = text.split('\n')
    result = []
    in_list = False
    in_table = False
    in_div = False

    for line in lines:
        stripped = line.strip()

        # Skip raw HTML we've already inserted
        if '<div class="data-entry-form">' in stripped:
            in_div = True
            result.append(line)
            continue
        if '</div>' in stripped and in_div:
            in_div = False
            result.append(line)
            continue
        if in_div:
            result.append(line)
            continue

        # Horizontal rule
        if stripped == '---' or stripped == '___':
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append('<hr>')
            continue

        # Headers
