            if in_list:
                result.append('</ul>')
                in_list = False
            result.append(f'<h3>{esc_html(stripped[4:])}</h3>')
            continue

        if stripped.startswith('#### '):
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append(f'<h4>{esc_html(stripped[5:])}</h4>')
            continue

        # Bold text lines
        if stripped.startswith('**') and stripped.endswith('**') and len(stripped) < 80:
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append(f'<p class="section-heading"><strong>{esc_html(stripped.strip("*"))}</strong></p>')
            continue

        # List items
        if stripped.startswith('- ') or stripped.startswith('* '):
            if not in_list:
                result.append('<ul>')
                in_list = True
            content = stripped[2:]
            # Bold markers
            content = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', content)
            # Italic markers
            content = re.sub(r'\*(.+?)\*', r'<em>\1</em>', content)
            result.append(f'<li>{content}</li>')
            continue

        # Numbered lists
        if re.match(r'^\d+\.\s+', stripped):
            if in_list and not re.match(r'^\d+\.\s+', result[-1] if result else ''):
                result.append('</ul>')
                in_list = False
            if not in_list:
                result.append('<ol>')
                in_list = True
            content = re.sub(r'^\d+\.\s+', '', stripped)
            content = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', content)
            content = re.sub(r'\*(.+?)\*', r'<em>\1</em>', content)
            result.append(f'<li>{content}</li>')
            continue

        # Empty line - close lists
        if not stripped:
            if in_list:
                result.append('</ul>')
                in_list = False
            result.append('')
            continue

        # Regular paragraph
        if in_list:
            result.append('</ul>')
            in_list = False

        content = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', stripped)
        content = re.sub(r'\*(.+?)\*', r'<em>\1</em>', content)
        result.append(f'<p>{content}</p>')

    if in_list:
        result.append('</ul>')

    return '\n'.join(result)


