# =============================================================
# Smart markdown-to-HTML: numbered sub-sections, clean formatting
# =============================================================
def chapter_md_to_html(text, ch_num):
    """
    Convert markdown within a chapter to HTML with numbered sub-sections.
    Section hierarchy: ## → 1.1, ### → 1.1.1, #### → 1.1.1.1
    """
    lines = text.split('\n')
    result = []
    in_ul = False
    in_ol = False

