        if stripped.startswith('<div') or stripped.startswith('</div') or stripped.startswith('<table') or stripped.startswith('</table') or stripped.startswith('<tr') or stripped.startswith('</tr') or stripped.startswith('<td') or stripped.startswith('</td') or stripped.startswith('<th') or stripped.startswith('</th') or stripped.startswith('<thead') or stripped.startswith('</thead') or stripped.startswith('<tbody') or stripped.startswith('</tbody'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            result.append(line); continue

        # --- Horizontal rules ---
        if stripped in ('---', '___', '***'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            result.append('<hr>'); continue

        # --- Empty line: close lists ---
        if not stripped:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            result.append(''); continue

        # --- Chapter-level headings (## Section) → major section ---
        if stripped.startswith('## ') and not stripped.startswith('## Chapter'):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            sec[0] += 1
            sec[1] = 0
            title = stripped[3:]
            num_label = f"{ch_num}.{sec[0]}"
            result.append(f'<h3 class="section-heading" id="s{ch_num}-{sec[0]}">{esc_html(num_label)} {esc_html(title)}</h3>')
            continue

        # --- Sub-section headings (###) → minor section ---
        if stripped.startswith('### '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            sec[1] += 1
            title = stripped[4:]
            num_label = f"{ch_num}.{sec[0]}.{sec[1]}" if sec[0] > 0 else f"{ch_num}.{sec[1]}"
            result.append(f'<h4 class="sub-section-heading" id="s{ch_num}-{sec[0]}-{sec[1]}">{esc_html(num_label)} {esc_html(title)}</h4>')
            continue

        # --- Sub-sub-section headings (####) ---
        if stripped.startswith('#### '):
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            title = stripped[5:]
