            result.append(f'<li class="checkbox-item"><span class="checkbox-box">{box}</span> {label}</li>')
            continue

        # --- Numbered list items ---
        num_match = re.match(r'^(\d+)\.\s+(.+)$', stripped)
        if num_match:
            if in_ul: result.append('</ul>'); in_ul = False
            if not in_ol: result.append('<ol>'); in_ol = True
            content = process_inline(num_match.group(2))
            result.append(f'<li>{content}</li>')
            continue

        # --- Bold + colons as subheadings ---
        bold_colon = re.match(r'^\*\*(.+?)\*\*:\s*(.*)$', stripped)
        if bold_colon:
            if in_ul: result.append('</ul>'); in_ul = False
            if in_ol: result.append('</ol>'); in_ol = False
            bold = bold_colon.group(1)
            rest = process_inline(bold_colon.group(2))
            if rest:
